/// Аспект двох знаків: відстань на зодіакальному колі 0–6
class Aspect {
  final String name, rel, sex, risk;
  final bool easy;
  const Aspect(this.name, this.easy, this.rel, this.sex, this.risk);
}

int aspectDistance(int a, int b) {
  final d = (a - b).abs() % 12;
  return d > 6 ? 12 - d : d;
}

const aspects = <Aspect>[
  Aspect('Один знак', true, 'Ви з одного знака, тож розумієте одне одного з півслова: *ті самі цінності, ті самі реакції*. Поруч легко, бо не треба нічого пояснювати. Головне завдання — не перетворитись на дзеркала, які лише повторюють одне одного.', 'Ви відчуваєте ритм одне одного без підказок, тому *хімія вмикається швидко*. Але й бажання у вас однакові, тож новизну доведеться приносити свідомо.', 'Ті самі слабкості помножені на два. Якщо обоє вперті або обоє уникають розмов, ніхто не поступиться першим.'),
  Aspect('Сусідні знаки', false, 'Ви сусіди на зодіакальному колі: стихії різні, і *кожен бачить у другому те, чого бракує самому*. Це стосунки-навчання: дратує, але й змушує рости. Потрібно більше слів, ніж здається.', 'Різний темп і різні мови бажання. *Цікаво саме через різницю*, якщо обоє готові питати й підказувати.', 'Дрібні непорозуміння накопичуються, бо здається, що все очевидно. Мовчання тут шкодить більше, ніж сварка.'),
  Aspect('Секстиль', true, 'Секстиль — аспект дружби і можливостей. Ваші стихії доповнюють одна одну, тож *разом легко щось починати*: плани, поїздки, спільні справи. Найкраще працює, коли ви обоє вкладаєтесь.', 'Легко, весело і без напруги. *Ви підхоплюєте ідеї одне одного*, і з часом стає тільки краще.', 'Можливості, якими не скористались. Якщо обоє чекають, що ініціативу візьме інший, все так і лишиться приємним, але поверховим.'),
  Aspect('Квадрат', false, 'Квадрат — класичний аспект напруги: ви з одного хреста, але різних стихій. *Іскрить і в хорошому, і в поганому сенсі*. Такі пари або вчаться домовлятися і стають дуже сильними, або втомлюються від постійного тертя.', 'Багато пристрасті саме через опір. *Примирення після сварки* в таких пар буває найкращим, але не варто будувати на цьому все.', 'Боротьба за владу і бажання переробити одне одного. Коли обоє тиснуть, ніхто не чує.'),
  Aspect('Тригон', true, 'Тригон — найгармонійніший аспект: одна стихія, різні знаки. *Вам просто добре разом*, без зусиль і пояснень. Підтримуєте одне одного природно, як дихаєте.', 'Природна сумісність: *тіла домовляються самі*. Темп, бажання й фантазії збігаються частіше, ніж зазвичай.', 'Занадто комфортно. Без викликів стосунки можуть заснути, тож іноді треба самим розхитувати човен.'),
  Aspect('Квінконс', false, 'Квінконс — найдивніший аспект: у вас немає нічого спільного ні в стихії, ні в хресті. *Вас тягне одне до одного, але важко пояснити чому*. Такі пари постійно підлаштовуються, і це або загартовує, або виснажує.', 'Непередбачувано: то дуже добре, то зовсім не в такт. *Треба вчитися мові одне одного* з нуля і не соромитись питати.', 'Відчуття, що постійно щось не так, хоча ніхто не винен. Легко почати змінювати себе до невпізнання.'),
  Aspect('Опозиція', true, 'Опозиція — протилежні знаки, які притягуються як магніти. Ваші стихії сумісні, але *кожен має те, чого бракує другому*. Разом ви ніби одна ціла картина, якщо не тягнете ковдру кожен на себе.', 'Сильне притягання протилежностей. *Напруга між вами — це паливо*, і її вистачає надовго.', 'Гойдалки: зближення, відштовхування і знову зближення. Важливо бачити в різниці доповнення, а не загрозу.'),
];

Aspect aspectOf(int a, int b) => aspects[aspectDistance(a, b)];
